// Two things the canonical verb promises that one agent-browser call cannot
// give: REPLACE semantics, and an optional Enter afterwards. agent-browser's
// type tool takes `clear`, which covers the first; `submit` needs a second
// call, which is why this verb is adapted rather than bound declaratively.
const typed = await callTool({
  selector: input.ref,
  text: input.text,
  clear: true,
});
if (!input.submit) {
  return { ok: true, ref: input.ref, submitted: false, raw: typed };
}
const pressed = await callNamed("agentbrowser__agent_browser_press", {
  key: "Enter",
});
return { ok: true, ref: input.ref, submitted: true, raw: { typed, pressed } };

// The canonical verb REQUIRES a tab_id, but agent-browser has no per-call tab
// argument — its snapshot acts on the session's active tab. Silently ignoring
// tab_id would make the verb lie about which tab it read. Switch first, then
// snapshot. The ids round-trip: browser__tabs returns agent-browser's own tab
// list, so whatever the model hands back is what tab_switch expects.
if (input.tab_id !== undefined && input.tab_id !== null && input.tab_id !== "") {
  await callNamed("agentbrowser__agent_browser_tab_switch", { tab: input.tab_id });
}
return await callTool({});

// Same tab-targeting gap as browser__snapshot: agent-browser screenshots the
// active tab, so honour the canonical tab_id by switching to it first rather
// than quietly capturing whichever tab happened to be in front.
if (input.tab_id !== undefined && input.tab_id !== null && input.tab_id !== "") {
  await callNamed("agentbrowser__agent_browser_tab_switch", { tab: input.tab_id });
}
return await callTool({});
